-- Replaces the Note table from V1 with notes --
-- Ids are generated by the database and the author is stored as a name, like case_log.performed_by --
CREATE TABLE notes(
    id         BIGINT       GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    case_id    BIGINT       NOT NULL REFERENCES cases(id),
    text       TEXT         NOT NULL,
    created_by VARCHAR(100) NOT NULL, -- Should maybe be changed to a foreign key to a user later?
    created_at TIMESTAMP    NOT NULL DEFAULT now(),
    CONSTRAINT notes_text_not_blank CHECK (length(trim(text)) > 0)
);

-- Copy existing rows --
INSERT INTO notes(id, case_id, text, created_by, created_at)
OVERRIDING SYSTEM VALUE -- To ADD the id and created_at from the old table
SELECT n.NoteID, n.CaseID, n.Content, COALESCE(u.Name, 'unknown'), n.CreatedAt
FROM Note n
LEFT JOIN User_Table u ON u.UserID = n.UserID;

SELECT setval(pg_get_serial_sequence('notes', 'id'), COALESCE(MAX(id), 0) + 1, false) FROM notes;

DROP TABLE Note;
